import {createMachine,step,instructions} from './accumulator-engine.js';
export function mount(root,{signal}){let m=createMachine();
  root.innerHTML='<p class="notice">Illustrative simulation: generic accumulator ISA written for this site, not Ethan’s coursework code or the official SCOMP spec. Signed, unbounded AC; separate program memory and return stack. Repeated subtraction divides a 16-bit input into four nibbles; memory[5] holds the maximum.</p><div class="prototype-controls"><label>Input word<select data-word><option value="299">0x012B</option><option value="291">0x0123</option><option value="65535">0xFFFF</option><option value="0">0x0000</option></select></label><button data-step>Clock / Step</button><button data-run>Run to HALT</button><button data-reset>Reset</button></div><div data-registers></div><div class="sub-viz" aria-live="polite"></div><div class="decision-columns"><div><h3>Memory inspector</h3><div data-memory></div></div><div><h3>Program / PC</h3><pre data-code></pre></div></div>';
  function draw(){root.dataset.pc=m.pc;root.dataset.ac=m.ac;root.dataset.halted=m.halted;root.querySelector('[data-registers]').textContent=`AC ${m.ac} · PC ${m.pc} · clocks ${m.cycles} · return stack [${m.stack}]${m.halted?' · HALT':''}`;const last=m.last;root.querySelector('.sub-viz').textContent=last?.op==='SUB'?`SUB: ${last.before} − ${last.operand} = ${last.after} · ${last.after<0?'negative → JNEG':last.after===0?'zero → JZERO':'positive'}`:'SUB visualization appears after a subtraction. Run uses SUB to compare the remainder with the current maximum.';root.querySelector('[data-memory]').innerHTML=m.memory.map((v,i)=>`<p>${i} · ${['word / quotient','divisor','one','quotient','nibbles left','maximum','remainder','zero'][i]}: <strong>${v}</strong></p>`).join('');root.querySelector('[data-code]').textContent=instructions.map(([op,arg],i)=>`${i===m.pc?'→':' '} ${String(i).padStart(2)} ${op} ${arg??''}`).join('\n');root.querySelector('[data-step]').disabled=m.halted;root.querySelector('[data-run]').disabled=m.halted;}
  root.addEventListener('click',e=>{if(e.target.matches('[data-step]'))step(m);if(e.target.matches('[data-run]')){let limit=50000;while(!m.halted&&limit--)step(m);}if(e.target.matches('[data-reset]'))m=createMachine(Number(root.querySelector('select').value));draw();},{signal});root.querySelector('select').addEventListener('change',()=>{m=createMachine(Number(root.querySelector('select').value));draw();},{signal});draw();return()=>root.replaceChildren();
}
